  const maxDimension = contractSource.match(/maxDimension:\s*([\d_]+)/)?.[1]?.replace(/_/g, "");
  const maxHeight = contractSource.match(/maxHeight:\s*([\d_]+)/)?.[1]?.replace(/_/g, "");
