type Declared = Record<string, string>;

function borders(widths: number[], colors = ["rgb(1, 2, 3)", "rgb(1, 2, 3)", "rgb(1, 2, 3)", "rgb(1, 2, 3)"], styles = ["solid", "solid", "solid", "solid"]): Declared {
