#!/usr/bin/env node
// Drives the local validation entry through Orca's signed-in embedded tab.
import { execFileSync } from "node:child_process";
import { writeFileSync } from "node:fs";

const [page, action, ...args] = process.argv.slice(2);
if (!page || !action) throw new Error("Usage: node scripts/importer-live-orca.mjs <browserPageId> open|run <nodes>|fixture <viewportIndex>|rotated-image|status|inspect <pageId>|focus <pageId> <layerNames...>|rotation-probe|pivot-probe|late-rotation-probe|delay-probe|cleanup <originalPageId> <testPageIds...>|network <output.json>");
const executable = process.env.ORCA_CLI_COMMAND || (process.env.ORCA_DEV_REPO_ROOT ? "orca-dev" : process.platform === "linux" ? "orca-ide" : "orca");
function call(command, options = []) {
  let output;
  try { output = execFileSync(executable, [command, "--page", page, ...options, "--json"], { encoding: "utf8", maxBuffer: 100 * 1024 * 1024 }); }
  catch (error) { output = error.stdout; if (!output) throw error; }
  const response = JSON.parse(output);
  if (!response.ok) throw new Error(JSON.stringify(response.error));
  return response.result;
}
function evaluate(expression) {
  const result = call("eval", ["--expression", expression]).result;
  try { return JSON.parse(result); } catch { return result; }
}
function send(command) {
  return evaluate(`(() => {window.phase5Frame.contentWindow.postMessage({phase5Command:${JSON.stringify(command)}},"http://localhost:4173");return "sent"})()`);
}

if (action === "open" || action === "connect") {
  if (action === "open") {
  let snapshot = call("snapshot");
  const close = snapshot.snapshot.match(/heading "Importer host validation"[^\n]*\n- button \[ref=(e\d+)\]/);
  if (close) { call("click", ["--element", `@${close[1]}`]); snapshot = call("snapshot"); }
  const openPattern = /StaticText "Ultimate HTML to Penpot"[\s\S]*?button "OPEN" \[ref=(e\d+)\]/;
  if (!openPattern.test(snapshot.snapshot)) {
    const plugins = Object.entries(snapshot.refs).find(([, ref]) => ref.name === "Plugins (Ctrl+Alt+P)");
    if (!plugins) throw new Error("Missing plugin manager button.");
    call("click", ["--element", `@${plugins[0]}`]);
  }
  for (let attempt = 0; attempt < 5; attempt++) { snapshot = call("snapshot"); if (openPattern.test(snapshot.snapshot)) break; }
  // Some paired Electron view sizes leave native click coordinates stale.
  // Use the same observed toolbar button through the DOM when that happens.
  if (!openPattern.test(snapshot.snapshot)) {
    evaluate('document.querySelector("button[data-tool=plugins]").click();"clicked"');
    snapshot = call("snapshot");
  }
  const open = snapshot.snapshot.match(openPattern);
  if (!open) throw new Error("The local importer must already be installed.");
  evaluate('(() => {const button=[...document.querySelectorAll("button")].find(b=>b.textContent.trim().toUpperCase()==="OPEN"&&b.parentElement.textContent.includes("Ultimate HTML to Penpot"));if(!button)throw Error("Missing local plugin row");button.click();return "opened"})()');
  for (let attempt = 0; attempt < 5; attempt++) { snapshot = call("snapshot"); if (snapshot.snapshot.includes('heading "Importer host validation"')) break; }
  }
  console.log(evaluate(`(() => {
    const frames=[];const scan=root=>{frames.push(...root.querySelectorAll("iframe"));for(const el of root.querySelectorAll("*"))if(el.shadowRoot)scan(el.shadowRoot)};scan(document);
    window.phase5Frame=frames.find(f=>f.src.includes("localhost:4173"));if(!window.phase5Frame)throw Error("Missing local validation frame");
    if(window.phase5Listener)removeEventListener("message",window.phase5Listener);
    window.phase5Results=[];window.phase5Listener=event=>{if(event.source===window.phase5Frame.contentWindow&&event.data?.phase5Result)window.phase5Results.push(event.data.phase5Result)};
    addEventListener("message",window.phase5Listener);return JSON.stringify({ready:true,hostVersion:window.penpotVersion,userAgent:navigator.userAgent});
  })()`));
} else if (action === "run" || action === "assets") {
  const size = Number(args[0]);
  if (!Number.isInteger(size) || size < 2 || size > (action === "assets" ? 120 : 20000)) throw new Error("Invalid workload size.");
  console.log(send({ action, size }));
} else if (action === "status") {
  console.log(JSON.stringify(evaluate('JSON.stringify({results:window.phase5Results.filter(r=>r.type!=="progress"),last:window.phase5Results.at(-1)})'), null, 2));
} else if (action === "inspect") {
  console.log(send({ action: "inspect", pageId: args[0] }));
} else if (action === "rotation-probe") {
  console.log(send({ action: "rotation-probe" }));
} else if (action === "pivot-probe") {
  console.log(send({ action: "pivot-probe" }));
} else if (action === "late-rotation-probe") {
  console.log(send({ action: "late-rotation-probe", size: Number(args[0] ?? 1) }));
} else if (action === "delay-probe") {
  console.log(send({ action: "delay-probe" }));
} else if (action === "rotated-image") {
  console.log(send({ action: "rotated-image", size: 0 }));
} else if (action === "fixture") {
  console.log(send({ action: "fixture", size: Number(args[0] || 0) }));
} else if (action === "focus") {
  console.log(send({ action: "focus", pageId: args[0], names: args.slice(1) }));
} else if (action === "list-pages") {
  console.log(send({ action: "list-pages" }));
} else if (action === "remove-boards") {
  console.log(send({ action: "remove-boards", pageId: args[0], boardIds: args.slice(1) }));
} else if (action === "cleanup") {
  console.log(send({ action: "cleanup", pageId: args[0], pageIds: args.slice(1) }));
} else if (action === "network") {
  const requests = call("network", ["--limit", "1000"]).requests.filter((request) => request.url.includes("/update-file"));
  const measurements = requests.map((request) => ({ timestamp: request.timestamp, status: request.status,
    requestBytes: Buffer.byteLength(request.postData || ""), serverTiming: request.responseHeaders?.["server-timing"] }));
  if (args[0]) writeFileSync(args[0], JSON.stringify(measurements, null, 2) + "\n");
  console.log(JSON.stringify(measurements, null, 2));
} else throw new Error(`Unknown action: ${action}`);
      const page = penpot.createPage();
      page.name = `${pagePrefix}delay probe`;
      await openPage(page);
      send({ type: "delay-probe", pageId: page.id, result: await delaySweepProbe() });
    } else if (message.action === "inspect") {
      const page = penpot.currentFile?.pages.find((candidate) => candidate.id === message.pageId);
      if (!page) throw new Error("Expected an existing page.");
      send({ type: "inspection", pageId: page.id, shapes: page.findShapes().length,
        topLevel: page.findShapes().filter((shape) => shape.parent?.id === page.root.id).map((shape) => ({ id: shape.id, name: shape.name, type: shape.type })),
        boards: page.findShapes({ type: "board" }).map((board) => ({ id: board.id, name: board.name, children: (board as import("@penpot/plugin-types").Board).children.length })),
        // Position, unrotated size, and the page position of the rotated top-left corner for every shape.
        geometry: page.findShapes().map((shape) => {
          const radians = (shape.rotation || 0) * Math.PI / 180;
          const cos = Math.cos(radians), sin = Math.sin(radians);
          const boundsWidth = Math.abs(shape.width * cos) + Math.abs(shape.height * sin), boundsHeight = Math.abs(shape.width * sin) + Math.abs(shape.height * cos);
          const centerX = shape.x + boundsWidth / 2, centerY = shape.y + boundsHeight / 2;
          return { id: shape.id, name: shape.name, type: shape.type, parentId: shape.parent?.id, x: shape.x, y: shape.y, width: shape.width, height: shape.height, rotation: shape.rotation,
            corner: { x: centerX + (-shape.width / 2) * cos - (-shape.height / 2) * sin, y: centerY + (-shape.width / 2) * sin + (-shape.height / 2) * cos } };
        }) });
    } else if (message.action === "focus") {
      const page = penpot.currentFile?.pages.find((candidate) => candidate.id === message.pageId);
      if (!page) throw new Error("Expected an existing page.");
      await openPage(page);
      const shapes = page.findShapes().filter((shape) => (message.names || []).includes(shape.name));
      if (shapes.length) penpot.viewport.zoomIntoView(shapes);
      send({ type: "focused", count: shapes.length });
    } else if (message.action === "list-pages") {
      send({ type: "pages", pages: penpot.currentFile?.pages.map((page) => ({ id: page.id, name: page.name, shapes: page.findShapes().length })), currentPageId: penpot.currentPage?.id });
    } else if (message.action === "remove-boards") {
      const page = penpot.currentFile?.pages.find((candidate) => candidate.id === message.pageId);
      if (!page) throw new Error("Expected an existing page.");
      await openPage(page);
      for (const id of message.boardIds || []) {
        const board = page.getShapeById(id);
        if (!board || board.type !== "board" || board.getPluginData("importer") !== "ultimate-html-to-penpot") throw new Error("Expected an imported validation board.");
        board.remove();
      }
      send({ type: "boards-removed" });
    } else if (message.action === "cleanup") {
      if (saveListener) penpot.off(saveListener);
      saveListener = undefined;
      const pages = penpot.currentFile?.pages || [];
      const original = pages.find((page) => page.id === (message.pageId || originalPageId));
      for (const id of message.pageIds || []) {
        const page = pages.find((candidate) => candidate.id === id);
        if (!page || !page.name.startsWith(pagePrefix)) throw new Error("Refusing to remove a page outside this validation run.");
        await openPage(page);
        for (const board of page.findShapes({ type: "board" }).filter((shape) => shape.id !== page.root.id)) board.remove();
      }
      if (original) await openPage(original);
      send({ type: "cleaned-up" });
    }
  } catch (error) {
    send({ type: "error", message: error instanceof Error ? error.message : String(error) });
  } finally { busy = false; }
});
A live test uses `https://design.penpot.app`, Penpot 2.18.1, through Orca's
embedded Windows Chromium 150.0.7871.250. The rectangular workload uses no
fonts or media. Without checkpoints, one 1,000-node attempt saved a 7.7 MB
request, while a repeat reached Penpot's "Error on saving" state. The failed
request had no recorded HTTP response, so this does not establish a universal
request-size threshold. A reload that raced a pending redo save is excluded
from successful reload evidence.

With checkpoints, 1,000 scene nodes produced one board with 999 children and
five save notifications. All five `update-file` requests returned HTTP 200;
the largest was 1,933,740 bytes, with 7,734,831 bytes across all five. Importer
processing took 130,225 ms, including 20,662 ms waiting for saves. After the
final acknowledged save and successful responses, a reload restored the same
board ID and all 999 children. This validates persistence for the recorded
workload, rather than promising a live import speedup.

A 500-node import, the smallest size that uses checkpoints, produced one board
with 499 children and three save notifications in 58,364 ms (11,952 ms waiting
for saves). A single Edit > Undo removed the whole board, leaving only the root
frame, and saved with HTTP 200 (3.18 MB). A single Edit > Redo restored the same
board with 499 children and saved with HTTP 200 (3.87 MB). The checkpoints
therefore keep the import in one undo block. Synthetic Ctrl+Z key presses sent
through Orca did not reach the workspace, so the menu commands were used.

The live media workload uploads 12 distinct generated PNGs at a peak concurrency
of three. Each image appears twice on each of three boards: all 72 image layers
have fills, the same 12 media IDs are reused across the boards, and no import
diagnostics occur. Processing takes 6,302 ms on this host. This validates the
real byte-upload path and sharing behavior; it is not a before/after speed test.

The host's upper persistence limit remains open. A mock pass at 20,000 nodes
is not proof that that workload saves in the live host. Keep the existing
layer/payload limits and workload warnings; do not infer a safe maximum from
layer count alone.

## Local live-harness procedure

The developer harness bundles the actual importer with an alternate entry;
it temporarily replaces ignored `dist/plugin.js` and `dist/index.html` and is
never included in the production build. It creates distinctly named validation
pages, validates scenes before mutations, reports import metrics and public
`contentsave` events, and can inspect saved layer counts after a reload.

With the normal local plugin already installed and `dist` built:

```sh
node scripts/importer-live-harness.mjs
npm run preview -- --host 0.0.0.0 --port 4173 --strictPort
orca-ide tab list --json
node scripts/importer-live-orca.mjs <browserPageId> open
node scripts/importer-live-orca.mjs <browserPageId> run 1000
node scripts/importer-live-orca.mjs <browserPageId> status
node scripts/importer-live-orca.mjs <browserPageId> network /tmp/save-requests.json
```

Use the executable selected by Orca's version-matched CLI skill on your platform.
The automation helper uses `ORCA_CLI_COMMAND` when configured. `connect`
reattaches its observation listener to an already-open harness after an
automation interruption. `assets 12` imports 12 distinct generated PNGs,
reused twice on each of three boards.

The transformed-geometry checks use the same harness. `fixture 0` imports the
desktop scene (index 0; 1 is tablet and 2 is mobile) of the checked-in
`transforms.html` baseline, with its assets inlined so no fixture server is
needed; set `PHASE5_FIXTURE=<file>` when running `importer-live-harness.mjs` to
embed another fixture's scenes. `rotated-image` imports a rotated image fill,

